import{_ as o,a0 as p,w as d,s as r,ao as l,I as i,x as a,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"使用 mDNS 在局域网中轻松发现系统 | LCTT x X-CMD","titleTemplate":false,"description":"使用 mDNS 在局域网中轻松发现系统 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 mDNS 在局域网中轻松发现系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 mDNS 在局域网中轻松发现系统 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180905 Find your systems easily on a LAN with mDNS","title":"使用 mDNS 在局域网中轻松发现系统","tag":"201809","desc":""},"relativePath":"201809/20180905 Find your systems easily on a LAN with mDNS.md","filePath":"[post].md"}'),h={name:"201809/20180905 Find your systems easily on a LAN with mDNS.md"};function g(m,s,u,k,b,f){const t=p("Link");return d(),r("div",null,[s[20]||(s[20]=l(`<h1 id="使用-mdns-在局域网中轻松发现系统" tabindex="-1">使用 mDNS 在局域网中轻松发现系统 <a class="header-anchor" href="#使用-mdns-在局域网中轻松发现系统" aria-label="Permalink to “使用 mDNS 在局域网中轻松发现系统”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2018/09/mDNS-816x345.jpg" alt=""></p><p>mDNS（<ruby>多播 DNS<rt>Multicast DNS</rt></ruby>）允许系统在局域网中广播查询其他资源的名称。Fedora 用户经常在没有复杂名称服务的路由器上接有多个 Linux 系统。在这种情况下，mDNS 允许你按名称与多个系统通信 —— 多数情况下不用路由器。你也不必在所有本地系统上同步类似 <code>/etc/hosts</code> 之类的文件。本文介绍如何设置它。</p><p>mDNS 是一个零配置网络服务，它已经诞生了很长一段时间。Fedora Workstation 带有零配置系统 Avahi（它包含 mDNS）。 （mDNS 也是 Bonjour 的一部分，可在 Mac OS 上找到。）</p><p>本文假设你有两个系统运行受支持的 Fedora 版本（27 或 28）。它们的主机名是 castor 和 pollux。</p><h3 id="安装包" tabindex="-1">安装包 <a class="header-anchor" href="#安装包" aria-label="Permalink to “安装包”">​</a></h3><p>确保系统上安装了 nss-mdns 和 avahi 软件包。你可能是不同的版本，这也没问题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm -q nss-mdns avahi</span></span>
<span class="line"><span>nss-mdns-0.14.1-1.fc28.x86_64</span></span>
<span class="line"><span>avahi-0.7-13.fc28.x86_64</span></span></code></pre></div><p>Fedora Workstation 默认提供这两个包。如果不存在，请安装它们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install nss-mdns avahi</span></span></code></pre></div><p>确保 <code>avahi-daemon.service</code> 单元已启用并正在运行。同样，这是 Fedora Workstation 的默认设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now avahi-daemon.service</span></span></code></pre></div><p>虽然是可选的，但你可能还需要安装 avahi-tools 软件包。该软件包包括许多方便的程序，用于检查系统上的零配置服务的工作情况。使用这个 <code>sudo</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install avahi-tools</span></span></code></pre></div><p><code>/etc/nsswitch.conf</code> 控制系统使用哪个服务用于解析，以及它们的顺序。你应该在那个文件中看到这样的一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>hosts: files mdns4_minimal [NOTFOUND=return] dns myhostname</span></span></code></pre></div><p>注意命令 <code>mdns4_minimal [NOTFOUND=return]</code>。它们告诉你的系统使用多播 DNS 解析程序将主机名解析为 IP 地址。即使该服务有效，如果名称无法解析，也会尝试其余服务。</p><p>如果你没有看到与此类似的配置，则可以（以 root 用户身份）对其进行编辑。但是，nss-mdns 包会为你处理此问题。如果你对自己编辑它感到不舒服，请删除并重新安装该软件包以修复该文件。</p><p>在<strong>两个系统</strong>中执行同样的步骤 。</p><h3 id="设置主机名并测试" tabindex="-1">设置主机名并测试 <a class="header-anchor" href="#设置主机名并测试" aria-label="Permalink to “设置主机名并测试”">​</a></h3><p>现在你已完成常见的配置工作，请使用以下方法之一设置每个主机的名称：</p>`,21)),i("ol",null,[i("li",null,[s[1]||(s[1]=a("如果你正在使用 Fedora Workstation，",-1)),e(t,{href:"https://fedoramagazine.org/set-hostname-fedora/"},{default:n(()=>[...s[0]||(s[0]=[a("你可以使用这个步骤",-1)])]),_:1}),s[2]||(s[2]=a("。",-1))]),s[3]||(s[3]=i("li",null,[a("如果没有，请使用 "),i("code",null,"hostnamectl"),a(" 来做。在第一台机器上这么做："),i("code",null,"$ hostnamectl set-hostname castor"),a("。")],-1)),s[4]||(s[4]=i("li",null,[a("你还可以编辑 "),i("code",null,"/etc/avahi/avahi-daemon.conf"),a("，删除主机名设置行上的注释，并在那里设置名称。但是，默认情况下，Avahi 使用系统提供的主机名，因此你"),i("strong",null,"不应该"),a("需要此方法。")],-1))]),s[21]||(s[21]=l(`<p>接下来，重启 Avahi 守护进程，以便它接收更改：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl restart avahi-daemon.service</span></span></code></pre></div><p>然后正确设置另一台机器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostnamectl set-hostname pollux</span></span>
<span class="line"><span>$ sudo systemctl restart avahi-daemon.service</span></span></code></pre></div><p>只要你的路由器没有禁止 mDNS 流量，你现在应该能够登录到 castor 并 ping 通另一台机器。你应该使用默认的 .local 域名，以便解析正常工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping pollux.local</span></span>
<span class="line"><span>PING pollux.local (192.168.0.1) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 192.168.0.1 (192.168.0.1): icmp_seq=1 ttl=64 time=3.17 ms</span></span>
<span class="line"><span>64 bytes from 192.168.0.1 (192.168.0.1): icmp_seq=2 ttl=64 time=1.24 ms</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>如果你在 pollux <code>ping castor.local</code>，同样的技巧也适用。现在在网络中访问你的系统更方便了！</p><p>此外，如果你的路由器也支持这个服务，请不要感到惊讶。现代 WiFi 和有线路由器通常提供这些服务，以使消费者的生活更轻松。</p><p>此过程适用于大多数系统。但是，如果遇到麻烦，请使用 avahi-browse 和 avahi-tools 软件包中的其他工具来查看可用的服务。</p><hr>`,10)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),e(t,{href:"https://fedoramagazine.org/find-systems-easily-lan-mdns/"},{default:n(()=>[...s[5]||(s[5]=[a("https://fedoramagazine.org/find-systems-easily-lan-mdns/",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),e(t,{href:"https://fedoramagazine.org/author/pfrields/"},{default:n(()=>[...s[7]||(s[7]=[a("Paul W. Frields",-1)])]),_:1}),s[12]||(s[12]=a(" \u2028选题：",-1)),e(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" \u2028译者：",-1)),e(t,{href:"https://github.com/geekpi"},{default:n(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" \u2028校对：",-1)),e(t,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原创编译，",-1)),e(t,{href:"https://linux.cn/"},{default:n(()=>[...s[16]||(s[16]=[a("Linux中国",-1)])]),_:1}),s[19]||(s[19]=a(" 荣誉推出",-1))])])}const N=o(h,[["render",g]]);export{v as __pageData,N as default};
